function plainText(v=''){const s=Array.isArray(v)?v.join(' '):String(v||'');return s.replace(/<[^>]+>/g,' ').replace(/&nbsp;/g,' ').replace(/\s+/g,' ').trim()}
function openGenre(doc){const s=plainText(doc.subject).toLowerCase();const map=[['film noir','Film Noir'],['horror','Horror'],['science fiction','Science Fiction'],['sci-fi','Science Fiction'],['comedy','Comedy'],['western','Western'],['mystery','Mystery'],['crime','Crime'],['romance','Romance'],['adventure','Adventure'],['documentary','Documentary'],['animation','Animation'],['cartoon','Animation'],['drama','Drama'],['war','War'],['music','Music']];for(const [needle,label] of map)if(s.includes(needle))return label;return state.openCinemaKind==='series'?'Classic TV':'Classic Film'}
function openDocToItem(d,kind){const id=String(d.identifier||'').trim();const y=String(d.year||d.date||'').match(/\b(18|19|20)\d{2}\b/)?.[0]||'';return{id:'ia:'+id,archiveId:id,openSource:true,type:kind==='series'?'series':'movie',title:plainText(d.title)||'Untitled',year:y,rating:'NR',genre:openGenre(d),quality:'Archive',description:plainText(d.description)||`Stream from the Internet Archive ${kind==='series'?'Classic TV':'Feature Films'} collection.`,art:`https://archive.org/services/img/${encodeURIComponent(id)}`,backdrop:`https://archive.org/services/img/${encodeURIComponent(id)}`,sourceName:'Internet Archive',downloads:Number(d.downloads||0),creator:plainText(d.creator)}}
function openCard(item){const fav=state.favorites.has(item.id);return `<article class="card posterCard openCard" tabindex="0" data-open-detail="${esc(item.id)}"><div class="cardArt" style="background-image:linear-gradient(180deg,transparent 42%,#07080dcf),url('${esc(item.art||fallbackArt)}')"><span class="quality">${esc(item.quality||'OPEN')}</span><span class="openBadge">OPEN</span>${fav?'<span class="badge" style="background:#6c5cff">MY LIST</span>':''}</div><b>${esc(item.title)}</b><small>${esc(item.genre||'Classic')} ${item.year?'• '+esc(item.year):''}</small></article>`}
function openRail(title,items){if(!items?.length)return'';return `<section class="railSection"><div class="railHead"><h2>${esc(title)}</h2><button data-view="open">Browse library ›</button></div><div class="rail">${items.slice(0,12).map(openCard).join('')}</div></section>`}
function archiveSearchUrl(kind,page=1,search='',sort='downloads desc'){const cfg=OPEN_COLLECTIONS[kind]||OPEN_COLLECTIONS.movie;let q=`collection:${cfg.collection} AND mediatype:movies`;const safe=String(search||'').replace(/["\\:()]/g,' ').replace(/\s+/g,' ').trim();if(safe)q+=` AND title:(${safe})`;const p=new URLSearchParams();p.set('q',q);['identifier','title','description','year','date','subject','creator','downloads'].forEach(f=>p.append('fl[]',f));p.append('sort[]',sort);p.set('rows','48');p.set('page',String(page));p.set('output','json');return `https://archive.org/advancedsearch.php?${p.toString()}`}
async function loadOpenCinema(kind=state.openCinemaKind,page=1,search=state.openCinemaSearch,append=false,sort=state.openCinemaSort){if(state.openCinemaLoading)return;state.openCinemaLoading=true;state.openCinemaError='';state.openCinemaKind=kind;state.openCinemaSearch=search||'';state.openCinemaSort=sort||'downloads desc';if(!append){state.openCinema=[];state.openCinemaPage=0}renderOpenLibrary();try{const r=await fetch(archiveSearchUrl(kind,page,search,sort),{mode:'cors'});if(!r.ok)throw new Error('Archive catalogue unavailable');const d=await r.json();const docs=d?.response?.docs||[];const items=docs.map(x=>openDocToItem(x,kind)).filter(x=>x.archiveId);state.openCinema=append?[...state.openCinema,...items]:items;state.openCinemaTotal=Number(d?.response?.numFound||items.length);state.openCinemaPage=page}catch(err){state.openCinemaError='The live archive index could not be reached from this browser. Showing verified open-movie fallbacks.';if(!append){state.openCinema=OPEN_FALLBACK.map(x=>({...x}));state.openCinemaTotal=state.openCinema.length;state.openCinemaPage=1}}finally{state.openCinemaLoading=false;renderOpenLibrary();renderHome()}}
function ensureOpenLibrary(){if(!state.openCinema.length&&!state.openCinemaLoading)loadOpenCinema('movie',1,'',false,'downloads desc')}
function renderOpenLibrary(){const el=document.getElementById('view-open');if(!el)return;if(state.profile.kids){el.innerHTML=`<div class="contentPage"><div class="openLibraryHero"><span class="heroEyebrow">KIDS PROFILE</span><h1>Open Library is hidden here.</h1><p>Switch to the primary profile to browse the unfiltered public-domain archive.</p></div></div>`;return}const cfg=OPEN_COLLECTIONS[state.openCinemaKind]||OPEN_COLLECTIONS.movie;const count=state.openCinemaTotal?state.openCinemaTotal.toLocaleString():'—';const cards=state.openCinema.map(openCard).join('');el.innerHTML=`<div class="contentPage openLibraryPage"><section class="openLibraryHero"><div><span class="heroEyebrow">${esc(cfg.eyebrow)}</span><h1>Open Library</h1><p>Real playable cinema and classic television from Internet Archive public-domain collections, presented inside Velora.</p></div><div class="openCount"><b>${count}</b><span>${esc(cfg.label)} items found</span></div></section><div class="openNotice"><b>Real content, not placeholder cards.</b><span>The source collection asks contributors to verify that submitted feature films/classic TV are public domain. Commercial premium channels and recent studio releases still require separate licensing.</span></div><div class="libraryTabs"><button class="chip ${state.openCinemaKind==='movie'?'active':''}" data-open-kind="movie">🎬 Feature Films</button><button class="chip ${state.openCinemaKind==='series'?'active':''}" data-open-kind="series">📺 Classic TV</button></div><form id="openSearchForm" class="libraryTools"><input id="openSearchInput" value="${esc(state.openCinemaSearch)}" placeholder="Search this open catalogue…"><select id="openSort"><option value="downloads desc" ${state.openCinemaSort==='downloads desc'?'selected':''}>Most watched</option><option value="date desc" ${state.openCinemaSort==='date desc'?'selected':''}>Newest first</option><option value="date asc" ${state.openCinemaSort==='date asc'?'selected':''}>Oldest first</option></select><button class="primary" type="submit">Search</button></form>${state.openCinemaError?`<div class="libraryError">${esc(state.openCinemaError)}</div>`:''}${state.openCinemaLoading&&!state.openCinema.length?`<div class="openLoading"><span></span><b>Loading ${esc(cfg.label)}…</b></div>`:''}<div class="catalogGrid openGrid">${cards}</div>${state.openCinema.length&&state.openCinema.length<state.openCinemaTotal?`<div class="loadMoreWrap"><button class="ghost" id="openLoadMore" ${state.openCinemaLoading?'disabled':''}>${state.openCinemaLoading?'Loading…':'Load 48 more'}</button><small>Showing ${state.openCinema.length.toLocaleString()} of ${count}</small></div>`:''}</div>`}
function findOpenItem(id){return state.openCinema.find(x=>x.id===id)||state.openSaved[id]||OPEN_FALLBACK.find(x=>x.id===id)}
function playOpenItem(id){const item=findOpenItem(id);if(!item)return;window.veloraTrack?.('play',{itemId:item.id||'',title:item.title||''});closeDetails();if(item.url){openPlayer(item);return}const frame=document.getElementById('archivePlayer'),video=document.getElementById('mainPlayer'),overlay=document.getElementById('playerOverlay');if(state.hls){state.hls.destroy();state.hls=null}video.pause();video.classList.add('hidden');video.removeAttribute('src');frame.classList.remove('hidden');frame.src=`https://archive.org/embed/${encodeURIComponent(item.archiveId)}?autoplay=1`;document.getElementById('playerTitle').textContent=item.title;document.getElementById('playerType').textContent='OPEN LIBRARY';document.getElementById('playerFav').textContent=state.favorites.has(item.id)?'♥':'♡';state.currentItem=item;overlay.classList.add('on');overlay.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';state.history=[item.id,...state.history.filter(x=>x!==item.id)].slice(0,20);persist()}
function showOpenDetails(id){const item=findOpenItem(id);if(!item)return;const modal=document.getElementById('detailsModal');document.getElementById('detailsCard').innerHTML=`<button class="circleBtn closeDetails" data-close-details>✕</button><div class="detailsHero openDetailsHero" style="background-image:url('${esc(item.backdrop||item.art||fallbackArt)}')"><div class="detailsCopy"><span class="heroEyebrow">OPEN LIBRARY • ${item.type==='series'?'CLASSIC TV':'FEATURE FILM'}</span><h1>${esc(item.title)}</h1><div class="meta">${item.year?`<span>${esc(item.year)}</span>`:''}<span>${esc(item.rating||'NR')}</span><span>${esc(item.genre||'Classic')}</span><span>Internet Archive</span></div><p>${esc(item.description||'Public-domain/open archive title.')}</p><p class="sourceLine">Source: <b>${esc(item.sourceName||'Internet Archive')}</b>${item.creator?` • ${esc(item.creator)}`:''}</p><div class="actions"><button class="primary" data-open-play="${esc(item.id)}">▶ Play now</button><button class="ghost" data-fav="${esc(item.id)}">${state.favorites.has(item.id)?'✓ My List':'＋ My List'}</button></div></div></div>`;modal.classList.add('on');document.body.style.overflow='hidden'}

function makeEpisodes(title,n){return Array.from({length:n},(_,i)=>({id:`${title}-${i+1}`,num:i+1,title:i===0?'New Beginnings':`Episode ${i+1}`,description:`${title} — episode ${i+1}. Demo episode metadata for the streaming interface.`,art:i%2?'https://images.unsplash.com/photo-1521295121783-8a321d551ad2?auto=format&fit=crop&w=800&q=80':'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80',url:i%2?SAMPLE_MP4:SAMPLE_HLS}))}
function esc(s=''){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('on');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('on'),2200)}
function persist(){store.set('favorites',[...state.favorites]);store.set('progress',state.progress);store.set('history',state.history);store.set('profile',state.profile);store.set('providers',state.providers);store.set('territory',state.territory);store.set('channels',state.channels);store.set('catalog',state.catalog);store.set('openSaved',state.openSaved)}
function initData(){state.channels=store.get('channels',DEMO_CHANNELS);state.catalog=store.get('catalog',DEMO_CATALOG);state.providers=store.get('providers',[DEMO_PROVIDER]);if(!state.channels.length)state.channels=[...DEMO_CHANNELS];if(!state.catalog.length)state.catalog=[...DEMO_CATALOG];if(!state.providers.length)state.providers=[DEMO_PROVIDER]}
function normTitle(s=''){return String(s).toLowerCase().replace(/\b(the|a|an)\b/g,' ').replace(/[^a-z0-9]+/g,' ').trim().replace(/\s+/g,' ')}
function catalogueKey(x){return `${x.type||'movie'}|${normTitle(x.title)}|${String(x.year||'').slice(0,4)}`}
function channelKey(x){return String(x.epgId||normTitle(x.name||'')).toLowerCase()}
function rightsActive(x,territory=state.territory){const r=x.rights||{};const ts=r.territories||[x.territory||'WORLD'];if(!ts.includes('WORLD')&&!ts.includes(territory))return false;const now=Date.now();if(r.starts&&Date.parse(r.starts)>now)return false;if(r.ends&&Date.parse(r.ends)<now)return false;return true}
function sourceEntry(x,provider){return {sourceId:provider.id,sourceName:provider.name,url:x.url||'',providerSeriesId:x.providerSeriesId||null,providerId:x.providerId||provider.id,territory:x.territory||provider.territory||'JM',priority:Number(x.priority??provider.priority??50),rights:x.rights||{territories:[provider.territory||'JM'],starts:provider.rightsStart||null,ends:provider.rightsEnd||null}}}
function mergeProviderData(provider,channels=[],catalog=[]){provider={status:'active',territory:'JM',priority:50,...provider};state.providers=[...state.providers.filter(p=>p.id!==provider.id),provider];for(const raw of channels){const x={...raw,sourceId:provider.id,sourceName:provider.name,territory:raw.territory||provider.territory,priority:Number(raw.priority??provider.priority),rights:raw.rights||{territories:[provider.territory||'JM'],starts:provider.rightsStart||null,ends:provider.rightsEnd||null}};const key=channelKey(x);const existing=state.channels.find(c=>channelKey(c)===key);const src=sourceEntry(x,provider);if(existing){existing.sources=[...(existing.sources||[sourceEntry(existing,{id:existing.sourceId||'legacy',name:existing.sourceName||'Legacy',territory:existing.territory||'WORLD',priority:existing.priority||1})]).filter(z=>z.sourceId!==provider.id),src];if(Number(x.priority||0)>Number(existing.priority||0)){Object.assign(existing,{...x,id:existing.id,sources:existing.sources})}}else state.channels.push({...x,sources:[src]})}
for(const raw of catalog){if(!raw?.title||!['movie','series'].includes(raw.type))continue;const x={...raw,sourceId:provider.id,sourceName:provider.name,territory:raw.territory||provider.territory,priority:Number(raw.priority??provider.priority),rights:raw.rights||{territories:[provider.territory||'JM'],starts:provider.rightsStart||null,ends:provider.rightsEnd||null}};const key=catalogueKey(x);const existing=state.catalog.find(c=>catalogueKey(c)===key);const src=sourceEntry(x,provider);if(existing){existing.sources=[...(existing.sources||[sourceEntry(existing,{id:existing.sourceId||'legacy',name:existing.sourceName||'Legacy',territory:existing.territory||'WORLD',priority:existing.priority||1})]).filter(z=>z.sourceId!==provider.id),src];if(Number(x.priority||0)>Number(existing.priority||0)&&rightsActive(x)){Object.assign(existing,{...x,id:existing.id,sources:existing.sources})}}else state.catalog.push({...x,sources:[src]})}
persist()}
function promoteRemaining(x){const sources=(x.sources||[]).sort((a,b)=>(b.priority||0)-(a.priority||0));const best=sources[0];return best?{...x,sourceId:best.sourceId,sourceName:best.sourceName,url:best.url||x.url,providerSeriesId:best.providerSeriesId||null,providerId:best.providerId||best.sourceId,territory:best.territory||x.territory,priority:best.priority||x.priority,rights:best.rights||x.rights,sources}:x}
function removeProviderLocal(id){state.providers=state.providers.filter(p=>p.id!==id);state.channels=state.channels.map(c=>({...c,sources:(c.sources||[]).filter(s=>s.sourceId!==id)})).filter(c=>c.sourceId!==id||(c.sources&&c.sources.length)).map(promoteRemaining);state.catalog=state.catalog.map(c=>({...c,sources:(c.sources||[]).filter(s=>s.sourceId!==id)})).filter(c=>c.sourceId!==id||(c.sources&&c.sources.length)).map(promoteRemaining);persist();renderAll()}
function filteredCatalog(){const base=state.catalog.filter(x=>rightsActive(x));return state.profile.kids?base.filter(x=>x.rating==='TV-Y'||x.genre==='Kids'):base}
function filteredChannels(){return state.channels.filter(x=>rightsActive(x))}
function card(item,poster=false){const p=state.progress[item.id]||0;const fav=state.favorites.has(item.id);const sc=item.sources?.length||1;return `<article class="card ${poster?'posterCard':''}" tabindex="0" data-detail="${esc(item.id)}"><div class="cardArt" style="background-image:linear-gradient(180deg,transparent 45%,#07080db5),url('${esc(item.art||item.backdrop||fallbackArt)}')"><span class="quality">${esc(item.quality||'HD')}</span>${sc>1?`<span class="sourceBadge">${sc} SOURCES</span>`:''}${fav?'<span class="badge" style="background:#6c5cff">MY LIST</span>':''}${p?`<span class="progressBar"><i style="width:${Math.min(p,100)}%"></i></span>`:''}</div><b>${esc(item.title)}</b><small>${esc(item.genre||item.type||'')} • ${esc(item.sourceName||'Velora')}</small></article>`}
function liveCard(ch){return `<article class="card" tabindex="0" data-live="${esc(ch.id)}"><div class="cardArt" style="background-image:linear-gradient(180deg,transparent 40%,#07080dcf),url('${fallbackArt}')"><span class="badge">LIVE</span></div><b>${esc(ch.name)}</b><small>${esc(ch.now||'Live now')}</small></article>`}
function rail(title,items,poster=false){if(!items.length)return'';return `<section class="railSection"><div class="railHead"><h2>${esc(title)}</h2><button>See all ›</button></div><div class="rail">${items.map(x=>card(x,poster)).join('')}</div></section>`}
function renderHome(){const cat=filteredCatalog();const hero=cat[0]||DEMO_CATALOG[0];const cont=state.history.map(id=>cat.find(x=>x.id===id)).filter(Boolean).slice(0,8);document.getElementById('view-home').innerHTML=`<div class="hero" style="background-image:url('${esc(hero.backdrop||hero.art)}')"><div class="heroCopy"><span class="heroEyebrow">VELORA FEATURED • ${esc(hero.genre)}</span><h1>${esc(hero.title)}</h1><div class="meta"><span>${hero.year}</span><span>${esc(hero.rating)}</span><span>${esc(hero.quality)}</span><span>${hero.type==='series'?'Series':'Movie'}</span></div><p>${esc(hero.description)}</p><div class="actions"><button class="primary" data-play="${esc(hero.id)}">▶ Play</button><button class="ghost" data-detail="${esc(hero.id)}">ⓘ More Info</button><button class="ghost" data-fav="${esc(hero.id)}">${state.favorites.has(hero.id)?'✓ My List':'＋ My List'}</button></div></div></div><div class="homeContent">${cont.length?rail('Continue Watching',cont):''}<section class="railSection"><div class="railHead"><h2>Live Now</h2><button data-view="live">See all ›</button></div><div class="rail">${filteredChannels().slice(0,6).map(liveCard).join('')}</div></section>${state.openCinema.length?openRail(`Open Cinema • ${state.openCinemaTotal?state.openCinemaTotal.toLocaleString()+' available':'Public Domain'}`,state.openCinema):''}${rail('Trending Now',cat.slice(1,8),false)}${rail('Movies',cat.filter(x=>x.type==='movie'),true)}${rail('Series',cat.filter(x=>x.type==='series'),true)}</div>`;
}
function renderCatalogView(type){const cat=filteredCatalog().filter(x=>x.type===type);const id=type==='movie'?'movies':'series';document.getElementById('view-'+id).innerHTML=`<div class="contentPage"><div class="pageHead"><div><span class="heroEyebrow">ON DEMAND</span><h1>${type==='movie'?'Movies':'Series'}</h1><p>One unified catalogue merged from every authorized source, filtered automatically for ${esc(state.territory)} rights.</p></div></div><div class="filterRow">${['All',...new Set(cat.map(x=>x.genre))].map((g,i)=>`<button class="chip ${i===0?'active':''}" data-filter="${esc(g)}" data-type="${type}">${esc(g)}</button>`).join('')}</div><div class="catalogGrid" id="grid-${id}">${cat.map(x=>card(x,true)).join('')}</div></div>`}
function renderMyList(){const local=filteredCatalog().filter(x=>state.favorites.has(x.id));const open=Object.values(state.openSaved||{}).filter(x=>state.favorites.has(x.id));const items=[...local,...open];document.getElementById('view-mylist').innerHTML=`<div class="contentPage"><div class="pageHead"><div><span class="heroEyebrow">PERSONAL</span><h1>My List</h1><p>Your saved movies, series and open-library classics stay with this demo profile.</p></div></div>${items.length?`<div class="catalogGrid">${items.map(x=>x.openSource?openCard(x):card(x,true)).join('')}</div>`:'<div class="empty">Your list is empty. Add something from Home, Movies, Series or Open Library.</div>'}</div>`}
function renderSearch(){document.getElementById('view-search').innerHTML=`<div class="contentPage"><div class="pageHead"><div><span class="heroEyebrow">UNIVERSAL SEARCH</span><h1>Find something</h1><p>Search channels, movies and series.</p></div></div><div class="searchBar"><input id="globalSearch" autocomplete="off" placeholder="Search titles, channels, genres…"></div><div id="searchResults"></div></div>`;drawSearch('')}
function drawSearch(q){const el=document.getElementById('searchResults');if(!el)return;const s=q.trim().toLowerCase();const items=filteredCatalog().filter(x=>!s||(x.title+' '+x.genre+' '+x.description).toLowerCase().includes(s));const channels=filteredChannels().filter(x=>!s||(x.name+' '+x.group+' '+(x.now||'')).toLowerCase().includes(s));el.innerHTML=`${channels.length?`<h2>Live TV</h2><div class="rail" style="padding-right:0">${channels.slice(0,8).map(liveCard).join('')}</div>`:''}<h2 style="margin-top:30px">Movies & Series</h2>${items.length?`<div class="catalogGrid">${items.map(x=>card(x,true)).join('')}</div>`:'<div class="empty">No results.</div>'}`}
function renderLive(){const liveChannels=filteredChannels();const groups=['All',...new Set(liveChannels.map(x=>x.group||'Other'))];document.getElementById('view-live').innerHTML=`<div class="contentPage"><div class="pageHead"><div><span class="heroEyebrow">LIVE TV</span><h1>Guide</h1><p>Fast channel list, Now/Next information and a TV-style EPG. Demo feeds use public test media.</p></div><span class="status"><i></i>${liveChannels.length} channels loaded</span></div><div class="liveLayout"><aside class="channelPane"><div class="channelToolbar"><input id="channelSearch" placeholder="Search channels…"></div><div class="channelCats">${groups.map((g,i)=>`<button class="chip ${i===0?'active':''}" data-group="${esc(g)}">${esc(g)}</button>`).join('')}</div><div class="channelList" id="channelList"></div></aside><div class="liveMain"><div class="livePlayerCard"><video id="inlineLive" controls playsinline></video><div class="nowPlaying"><div><span class="heroEyebrow">NOW PLAYING</span><h2 id="nowChannel">Choose a channel</h2><p id="nowProgram">Select a channel from the left.</p></div><button class="ghost" id="openFullLive">⛶ Fullscreen Player</button></div></div><div class="guide"><div class="guideHead"><div>CHANNEL</div><div>NOW</div><div>NEXT</div><div>LATER</div><div>TONIGHT</div></div><div class="guideBody" id="guideBody"></div></div></div></div></div>`;drawChannelList();drawGuide();if(liveChannels[0])selectChannel(liveChannels[0].id,false)}
function drawChannelList(q=''){const el=document.getElementById('channelList');if(!el)return;const grp=state.currentFilter;const s=q.toLowerCase();const list=filteredChannels().filter(c=>(grp==='All'||c.group===grp)&&(!s||(c.name+' '+c.group+' '+(c.now||'')).toLowerCase().includes(s)));el.innerHTML=list.map(c=>`<button class="channelRow ${state.currentChannel?.id===c.id?'active':''}" data-channel="${esc(c.id)}"><span class="channelLogo">${c.logo?`<img src="${esc(c.logo)}" alt="">`:'TV'}</span><span><b>${esc(c.name)}</b><small>${esc(c.now||'Live')}</small></span><span class="channelNum">${esc(c.num||'')}</span></button>`).join('')}
function programSet(c){const x=state.epg[c.id]||state.epg[c.name];if(x&&x.length)return x.slice(0,4);return [{title:c.now||'Live Programming',time:'Now'},{title:c.next||'Up Next',time:'+30m'},{title:'Featured Programme',time:'+1h'},{title:'Evening Lineup',time:'+2h'}]}
function drawGuide(){const el=document.getElementById('guideBody');if(!el)return;el.innerHTML=filteredChannels().map(c=>`<div class="guideRow"><div class="guideChannel"><b>${esc(c.num||'')} ${esc(c.name)}</b><br><small>${esc(c.group||'')}</small></div>${programSet(c).map((p,i)=>`<button class="program ${i===0?'current':''}" data-channel="${esc(c.id)}"><b>${esc(p.title)}</b><small>${esc(p.time||'')}</small></button>`).join('')}</div>`).join('')}
function selectChannel(id,autoplay=true){const c=filteredChannels().find(x=>x.id===id);if(!c)return;state.currentChannel=c;drawChannelList(document.getElementById('channelSearch')?.value||'');const t=document.getElementById('nowChannel'),p=document.getElementById('nowProgram');if(t)t.textContent=c.name;if(p)p.textContent=`${c.now||'Live'} • ${c.group||''}`;const v=document.getElementById('inlineLive');if(v)playInto(v,c.url,autoplay);state.history=[c.id,...state.history.filter(x=>x!==c.id)].slice(0,20);persist()}
function playInto(video,url,autoplay=true,start=0){if(state.hls){state.hls.destroy();state.hls=null} video.pause();video.removeAttribute('src');if(!url)return;if(url.includes('.m3u8')&&window.Hls&&Hls.isSupported()){const h=new Hls({enableWorker:true,lowLatencyMode:true});state.hls=h;h.loadSource(url);h.attachMedia(video);h.on(Hls.Events.MANIFEST_PARSED,()=>{if(start)video.currentTime=start;if(autoplay)video.play().catch(()=>{})});h.on(Hls.Events.ERROR,(_,d)=>{if(d.fatal)toast('Stream could not be played. Try another channel.')})}else{video.src=url;video.addEventListener('loadedmetadata',()=>{if(start)video.currentTime=Math.min(start,video.duration||start);if(autoplay)video.play().catch(()=>{})},{once:true})}}
function choosePlayback(item){if(!item?.sources?.length)return item;const active=item.sources.filter(s=>rightsActive({rights:s.rights,territory:s.territory})).sort((a,b)=>(b.priority||0)-(a.priority||0));const best=active[0];return best?{...item,url:best.url||item.url,providerSeriesId:best.providerSeriesId||item.providerSeriesId,providerId:best.providerId||item.providerId,sourceId:best.sourceId||item.sourceId,sourceName:best.sourceName||item.sourceName}:item}
function openPlayer(itemOrChannel){window.veloraTrack?.('play',{itemId:itemOrChannel?.id||'',title:itemOrChannel?.title||itemOrChannel?.name||''});const archiveFrame=document.getElementById('archivePlayer'),mainVideo=document.getElementById('mainPlayer');if(archiveFrame){archiveFrame.src='about:blank';archiveFrame.classList.add('hidden')}if(mainVideo)mainVideo.classList.remove('hidden');itemOrChannel=choosePlayback(itemOrChannel);const isCh=itemOrChannel.url&&itemOrChannel.name&&!itemOrChannel.title;const title=isCh?itemOrChannel.name:itemOrChannel.title;const type=isCh?'LIVE TV':itemOrChannel.type==='series'?'SERIES':'MOVIE';state.currentItem=itemOrChannel;const o=document.getElementById('playerOverlay'),v=document.getElementById('mainPlayer');document.getElementById('playerTitle').textContent=title;document.getElementById('playerType').textContent=type;document.getElementById('playerFav').textContent=state.favorites.has(itemOrChannel.id)?'♥':'♡';o.classList.add('on');o.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';let start=0;if(!isCh&&state.progress[itemOrChannel.id])start=(state.progress[itemOrChannel.id]/100)*(itemOrChannel._duration||0);playInto(v,itemOrChannel.url,true,start);if(!isCh){v.ontimeupdate=()=>{if(v.duration&&Number.isFinite(v.duration)){state.progress[itemOrChannel.id]=Math.round(v.currentTime/v.duration*100);itemOrChannel._duration=v.duration;persist()}};state.history=[itemOrChannel.id,...state.history.filter(x=>x!==itemOrChannel.id)].slice(0,20);persist()} if(isCh)showChannelOverlay()}
function showChannelOverlay(){const box=document.getElementById('channelOverlay');box.innerHTML=state.channels.map(c=>`<button class="channelRow ${state.currentItem?.id===c.id?'active':''}" data-overlay-channel="${esc(c.id)}"><span class="channelLogo">TV</span><span><b>${esc(c.name)}</b><small>${esc(c.now||'Live')}</small></span><span class="channelNum">${esc(c.num||'')}</span></button>`).join('');box.classList.add('on');clearTimeout(showChannelOverlay.t);showChannelOverlay.t=setTimeout(()=>box.classList.remove('on'),5000)}
function closePlayer(){const o=document.getElementById('playerOverlay'),v=document.getElementById('mainPlayer'),a=document.getElementById('archivePlayer');v.pause();v.ontimeupdate=null;if(state.hls){state.hls.destroy();state.hls=null}v.removeAttribute('src');v.classList.remove('hidden');if(a){a.src='about:blank';a.classList.add('hidden')}o.classList.remove('on');o.setAttribute('aria-hidden','true');document.body.style.overflow='';renderHome()}
function toggleFavorite(id){if(state.favorites.has(id)){state.favorites.delete(id);delete state.openSaved[id]}else{state.favorites.add(id);const oi=findOpenItem(id);if(oi?.openSource)state.openSaved[id]={...oi}}persist();toast(state.favorites.has(id)?'Added to My List':'Removed from My List');renderHome();renderMyList();renderOpenLibrary()}
async function showDetails(id){const baseItem=state.catalog.find(x=>x.id===id);if(!baseItem)return;const item=choosePlayback(baseItem);if(item.providerSeriesId&&!baseItem.episodes){if(!location.protocol.startsWith('http')){toast('Run node server.mjs to load provider episodes.')}else{try{toast('Loading episodes…');const r=await fetch(`/api/providers/${item.providerId||item.sourceId}/xtream/series/${item.providerSeriesId}`);const d=await r.json();if(r.ok&&d.episodes){baseItem.episodes=d.episodes;item.episodes=d.episodes;store.set('catalog',state.catalog)}else toast(d.error||'Could not load episodes')}catch{toast('Provider episode sync failed')}}}const modal=document.getElementById('detailsModal');document.getElementById('detailsCard').innerHTML=`<button class="circleBtn closeDetails" data-close-details>✕</button><div class="detailsHero" style="background-image:url('${esc(item.backdrop||item.art)}')"><div class="detailsCopy"><span class="heroEyebrow">${item.type==='series'?'SERIES':'MOVIE'}</span><h1>${esc(item.title)}</h1><div class="meta"><span>${item.year}</span><span>${esc(item.rating)}</span><span>${esc(item.quality)}</span><span>${esc(item.genre)}</span></div><p>${esc(item.description)}</p><p class="sourceLine">Available from <b>${esc(item.sourceName||'Velora')}</b>${item.sources?.length>1?` • ${item.sources.length} authorized sources`:''} • Territory ${esc(state.territory)}</p><div class="actions"><button class="primary" data-play="${esc(item.id)}">▶ ${state.progress[item.id]?'Resume':'Play'}</button><button class="ghost" data-fav="${esc(item.id)}">${state.favorites.has(item.id)?'✓ My List':'＋ My List'}</button></div></div></div>${item.episodes?`<div class="episodeList"><h2>Season 1</h2>${item.episodes.map(e=>`<div class="episode"><img src="${esc(e.art)}" alt=""><div><b>${e.num}. ${esc(e.title)}</b><p>${esc(e.description)}</p></div><button class="ghost" data-episode="${esc(item.id)}" data-episode-num="${e.num}">▶ Play</button></div>`).join('')}</div>`:''}`;modal.classList.add('on');document.body.style.overflow='hidden'}
function closeDetails(){document.getElementById('detailsModal').classList.remove('on');document.body.style.overflow=''}
function renderSettings(){document.getElementById('view-settings').innerHTML=`<div class="contentPage"><div class="pageHead"><div><span class="heroEyebrow">ACCOUNT</span><h1>Settings</h1><p>Playback, profile and device preferences.</p></div></div><div class="settingsGrid"><section class="panel"><h2>Playback</h2><p>These preferences are stored locally in this prototype.</p><div class="settingRow"><span>Autoplay next episode</span><button class="switch on"></button></div><div class="settingRow"><span>Start live channels automatically</span><button class="switch on"></button></div><div class="settingRow"><span>Prefer highest available quality</span><button class="switch on"></button></div></section><section class="panel"><h2>Profile</h2><div class="settingRow"><span>Profile name</span><b>${esc(state.profile.name)}</b></div><div class="settingRow"><span>Kids mode</span><b>${state.profile.kids?'On':'Off'}</b></div><div class="settingRow"><span>Plan</span><b>Family Demo</b></div><div class="settingRow"><span>Simultaneous streams</span><b>3</b></div></section><section class="panel"><h2>Devices</h2><p>Demo device management.</p><div class="settingRow"><span>This browser</span><b>Active now</b></div><div class="settingRow"><span>Living Room TV</span><button class="ghost">Sign out</button></div></section><section class="panel"><h2>About this build</h2><p>Velora is an original prototype modeled on the convenience of premium IPTV/OTT apps. It does not include copyrighted commercial channels or bypass DRM.</p></section></div></div>`}
function renderAdmin(){const sourceAssets=state.catalog.reduce((n,x)=>n+(x.sources?.length||1),0);const dupes=Math.max(0,sourceAssets-state.catalog.length);const providerRows=state.providers.map(p=>`<div class="feedRow"><div><b>${esc(p.name)}</b><small>${esc((p.type||'feed').toUpperCase())} • ${esc(p.territory||'JM')} • priority ${esc(p.priority||50)}</small></div><div class="providerActions"><span class="status compact"><i></i>${esc(p.status||'active')}</span>${p.id!==DEMO_PROVIDER.id?`<button class="ghost tiny" data-remove-source="${esc(p.id)}">Remove</button>`:''}</div></div>`).join('');document.getElementById('view-admin').innerHTML=`<div class="contentPage"><div class="pageHead"><div><span class="heroEyebrow">CATALOGUE HUB</span><h1>Sources, rights & feeds</h1><p>Combine multiple authorized catalogues into one Velora library. Duplicate titles are merged, rights windows are respected, and the highest-priority available source is used for playback.</p></div><span class="status"><i></i>${state.providers.length} sources</span></div><div class="statsStrip"><div><b>${state.channels.length}</b><span>Live channels</span></div><div><b>${state.catalog.length}</b><span>Unique VOD titles</span></div><div><b>${sourceAssets}</b><span>Source assets</span></div><div><b>${dupes}</b><span>Duplicates merged</span></div></div><div class="adminGrid"><section class="panel widePanel"><h2>Catalogue sources</h2><p>These are the sources currently merged into the customer library.</p><div class="feedList">${providerRows||'<div class="empty">No sources connected.</div>'}</div></section><section class="panel"><h2>Customer territory</h2><p>Only titles with active rights for this territory are shown.</p><div class="formGrid"><select id="territorySelect"><option value="JM" ${state.territory==='JM'?'selected':''}>Jamaica (JM)</option><option value="US" ${state.territory==='US'?'selected':''}>United States (US)</option><option value="GB" ${state.territory==='GB'?'selected':''}>United Kingdom (GB)</option><option value="CA" ${state.territory==='CA'?'selected':''}>Canada (CA)</option></select><button class="ghost full" id="saveTerritory">Apply territory</button></div></section><section class="panel"><h2>Connect IPTV / OTT feed</h2><p>Add an authorized Xtream-compatible provider. The server keeps credentials away from subscribers.</p><div class="formGrid"><input id="providerName" placeholder="Provider name"><input id="providerServer" placeholder="https://provider.example"><input id="providerUsername" placeholder="Username"><input id="providerPassword" type="password" placeholder="Password"><input id="providerTerritory" value="JM" placeholder="Rights territory e.g. JM"><input id="providerPriority" type="number" min="1" max="100" value="50" placeholder="Priority"><input id="providerRightsStart" type="date" title="Rights start"><input id="providerRightsEnd" type="date" title="Rights end"><button class="primary full" id="connectorSync">Connect & merge authorized provider</button></div></section><section class="panel"><h2>Import catalogue JSON</h2><p>Import movies/series exported by a distributor or rights system. The sample file documents the schema.</p><label class="uploadBox">Choose catalogue JSON<input id="catalogFile" type="file" accept=".json,application/json"></label><a class="ghost linkButton" href="demo-authorized-catalog.json" download>Download sample schema</a></section><section class="panel"><h2>Import distributor CSV</h2><p>Import machine-readable movie/series metadata. Supports common fields such as title, type, year, genre, artwork, playback URL and rights windows.</p><div class="formGrid"><input id="csvProviderName" value="Distributor CSV" placeholder="Source name"><input id="csvTerritory" value="JM" placeholder="Default territory"></div><label class="uploadBox">Choose metadata CSV<input id="csvFile" type="file" accept=".csv,text/csv"></label><a class="ghost linkButton" href="demo-distributor-catalog.csv" download>Download sample CSV</a></section><section class="panel"><h2>Import Live TV M3U</h2><p>Add an authorized playlist without replacing your existing channels.</p><div class="formGrid"><input id="m3uProviderName" value="Local M3U Provider" placeholder="Source name"><input id="m3uTerritory" value="JM" placeholder="Rights territory"></div><label class="uploadBox">Choose M3U file<input id="m3uFile" type="file" accept=".m3u,.m3u8,text/plain"></label></section><section class="panel"><h2>Import XMLTV EPG</h2><p>Load programme-guide metadata and map it to channel IDs or names.</p><label class="uploadBox">Choose XMLTV file<input id="xmltvFile" type="file" accept=".xml,.xmltv,text/xml"></label></section><section class="panel widePanel"><h2>Distribution pipeline</h2><p>Velora is ready to accept distributor feeds once you have contracts/API access. These adapters are intentionally not pretending to have credentials we do not possess.</p><div class="marketGrid"><div><b>FAST / linear distributor</b><small>Channels + VOD + EPG</small><span>Feed/API contract required</span></div><div><b>Film distributor</b><small>Movies + series metadata/assets</small><span>Delivery feed required</span></div><div><b>Rights marketplace</b><small>Territory + rights windows</small><span>Licensed acquisitions required</span></div><div><b>Direct broadcaster</b><small>Local/live channel carriage</small><span>Carriage authorization required</span></div></div></section><section class="panel"><h2>Restore open demo</h2><p>Re-add Velora's public/demo media without removing connected sources.</p><button class="ghost" id="restoreDemo">Add demo source</button></section><section class="panel"><h2>Reset prototype</h2><p>Clear imported feeds, favourites and progress.</p><button class="ghost danger" id="resetApp">Reset local data</button></section></div></div>`}
async function connectProvider(){if(!location.protocol.startsWith('http'))return toast('Run node server.mjs first to use secure provider sync.');const name=document.getElementById('providerName')?.value.trim()||'Authorized Provider',serverUrl=document.getElementById('providerServer')?.value.trim(),username=document.getElementById('providerUsername')?.value.trim(),password=document.getElementById('providerPassword')?.value,territory=(document.getElementById('providerTerritory')?.value.trim()||'JM').toUpperCase(),priority=Number(document.getElementById('providerPriority')?.value||50),rightsStart=document.getElementById('providerRightsStart')?.value||null,rightsEnd=document.getElementById('providerRightsEnd')?.value||null;if(!serverUrl||!username||!password)return toast('Enter server URL, username and password.');const btn=document.getElementById('connectorSync');if(btn){btn.disabled=true;btn.textContent='Connecting & merging…'}try{const r=await fetch('/api/providers/xtream/connect',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name,serverUrl,username,password,territory,priority,rightsStart,rightsEnd})});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Connection failed');mergeProviderData(d.provider,d.channels||[],d.catalog||[]);try{const er=await fetch(`/api/providers/${d.provider.id}/epg`);if(er.ok){const parsed=parseXMLTV(await er.text());for(const [k,v] of Object.entries(parsed))state.epg[k]=v;store.set('epg',state.epg)}}catch{}renderAll();showView('admin');toast(`Merged ${d.channels.length} channels and ${d.catalog.length} source titles`)}catch(e){toast(e.message||'Provider sync failed')}finally{const b=document.getElementById('connectorSync');if(b){b.disabled=false;b.textContent='Connect & merge authorized provider'}}}
function parseM3U(text){const lines=text.replace(/\r/g,'').split('\n');const out=[];let meta=null;for(const raw of lines){const line=raw.trim();if(line.startsWith('#EXTINF:')){const attr={};for(const m of line.matchAll(/([\w-]+)="([^"]*)"/g))attr[m[1]]=m[2];const name=(line.split(',').slice(1).join(',')||attr['tvg-name']||'Channel').trim();meta={id:attr['tvg-id']||slug(name)+'-'+out.length,num:String(out.length+1).padStart(3,'0'),name,group:attr['group-title']||'Other',logo:attr['tvg-logo']||'',now:'Live',next:'',desc:'Imported authorized feed'}}else if(line&&!line.startsWith('#')&&meta){out.push({...meta,url:line});meta=null}}return out}
function parseCSV(text){const rows=[];let row=[],cell='',q=false;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(c==='"'&&q&&n==='"'){cell+='"';i++;continue}if(c==='"'){q=!q;continue}if(c===','&&!q){row.push(cell);cell='';continue}if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&n==='\n')i++;row.push(cell);cell='';if(row.some(x=>x.trim()!==''))rows.push(row);row=[];continue}cell+=c}row.push(cell);if(row.some(x=>x.trim()!==''))rows.push(row);if(rows.length<2)return[];const headers=rows[0].map(h=>h.trim().toLowerCase().replace(/[^a-z0-9]+/g,'_'));return rows.slice(1).map(r=>Object.fromEntries(headers.map((h,i)=>[h,(r[i]||'').trim()]))) }
function csvToCatalog(text,provider){const rows=parseCSV(text);const val=(r,...keys)=>{for(const k of keys)if(r[k])return r[k];return''};return rows.map((r,i)=>{const title=val(r,'title','name','program_title');if(!title)return null;const rawType=val(r,'type','format','content_type').toLowerCase();const type=rawType.includes('series')||rawType.includes('show')?'series':'movie';const territories=val(r,'territories','territory','avail_territories').split(/[|; ]+/).filter(Boolean).map(x=>x.toUpperCase());return {id:`${provider.id}:csv:${i}`,type,title,year:val(r,'year','production_year','release_year'),rating:val(r,'rating','content_rating')||'NR',genre:val(r,'genre','genres','category')||'Other',quality:val(r,'quality','resolution')||'HD',description:val(r,'description','synopsis','plot','long_description'),art:val(r,'art','poster','poster_url','image_2_3'),backdrop:val(r,'backdrop','backdrop_url','image_16_9'),url:val(r,'url','stream_url','playback_url','video_url'),rights:{territories:territories.length?territories:[provider.territory||'JM'],starts:val(r,'rights_start','start_date','license_start')||provider.rightsStart||null,ends:val(r,'rights_end','end_date','license_end')||provider.rightsEnd||null}}}).filter(Boolean)}
function parseXMLTV(text){const doc=new DOMParser().parseFromString(text,'text/xml');const out={};const names={};doc.querySelectorAll('channel').forEach(ch=>{const id=ch.getAttribute('id');const name=ch.querySelector('display-name')?.textContent?.trim();if(id&&name)names[id]=name});doc.querySelectorAll('programme').forEach(p=>{const id=p.getAttribute('channel');const title=p.querySelector('title')?.textContent?.trim()||'Programme';const start=p.getAttribute('start')||'';const key=id;out[key]??=[];out[key].push({title,time:formatXmlTime(start)});if(names[id]){out[names[id]]??=[];out[names[id]].push({title,time:formatXmlTime(start)})}});Object.values(out).forEach(a=>a.sort((x,y)=>x.time.localeCompare(y.time)));return out}
function formatXmlTime(v){if(!v||v.length<12)return'';return `${v.slice(8,10)}:${v.slice(10,12)}`}
function slug(s){return s.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}
function showView(name){if(name==='admin'&&state.user?.role!=='admin'){toast('Admin access is restricted to the VELORA owner.');name='home'}window.veloraTrack?.('view',{view:name});document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));document.getElementById('view-'+name)?.classList.add('active');document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));document.getElementById('profileMenu').classList.remove('on');if(name==='home')renderHome();if(name==='live')renderLive();if(name==='movies')renderCatalogView('movie');if(name==='series')renderCatalogView('series');if(name==='open'){renderOpenLibrary();if(!state.profile.kids)ensureOpenLibrary()}if(name==='search')renderSearch();if(name==='mylist')renderMyList();if(name==='settings')renderSettings();if(name==='admin')renderAdmin();window.scrollTo({top:0,behavior:'instant'})}
function applyProfile(){
  const baseName=state.user?.name||state.profile.name||'Viewer';
  const shown=state.profile.kids?'Kids':baseName;
  state.profile={...state.profile,name:shown};
  document.getElementById('profileName').textContent=shown;
  document.getElementById('avatar').textContent=state.profile.kids?'K':shown.charAt(0).toUpperCase();
  const menuName=document.getElementById('menuProfileName');if(menuName)menuName.textContent=shown;
  const menuAvatar=document.getElementById('menuAvatar');if(menuAvatar)menuAvatar.textContent=state.profile.kids?'K':shown.charAt(0).toUpperCase();
  const menuRole=document.getElementById('menuProfileRole');if(menuRole)menuRole.textContent=state.user?.role==='admin'?'Owner / Admin':'Tester profile';
  const adminBtn=document.getElementById('adminMenuBtn');if(adminBtn)adminBtn.classList.toggle('hidden',state.user?.role!=='admin');
  document.body.classList.toggle('kids',state.profile.kids);
  document.body.classList.toggle('veloraAdmin',state.user?.role==='admin');
}
window.veloraEnterApp=function(user){
  state.user=user;
  state.profile={name:user?.name||'Viewer',kids:false};
  store.set('profile',state.profile);
  document.getElementById('login').classList.add('hidden');
  document.getElementById('app').classList.remove('hidden');
  applyProfile();renderAll();showView('home');ensureOpenLibrary();
}
window.veloraExitApp=function(){
  state.user=null;
  state.profile={name:'Viewer',kids:false};
  document.getElementById('app').classList.add('hidden');
  document.getElementById('login').classList.remove('hidden');
  document.getElementById('profileMenu')?.classList.remove('on');
}
function logout(){if(window.VeloraAuth?.logout)return window.VeloraAuth.logout();window.veloraExitApp()}
function renderAll(){renderHome();renderLive();renderCatalogView('movie');renderCatalogView('series');renderOpenLibrary();renderSearch();renderMyList();renderSettings();if(state.user?.role==='admin')renderAdmin()}
initData();
document.getElementById('profileBtn').addEventListener('click',()=>document.getElementById('profileMenu').classList.toggle('on'));
document.getElementById('signOut').addEventListener('click',logout);
document.getElementById('kidsMode').addEventListener('click',()=>{const base=state.user?.name||'Viewer';state.profile=state.profile.kids?{name:base,kids:false}:{name:'Kids',kids:true};persist();applyProfile();showView('home');toast(state.profile.kids?'Kids profile enabled':'Primary profile enabled')});
document.addEventListener('click',e=>{const v=e.target.closest('[data-view]');if(v){showView(v.dataset.view);return}const d=e.target.closest('[data-detail]');if(d){showDetails(d.dataset.detail);return}const pl=e.target.closest('[data-play]');if(pl){const item=state.catalog.find(x=>x.id===pl.dataset.play);if(item){if(item.type==='series'&&!item.url){showDetails(item.id)}else{closeDetails();openPlayer(item)}}return}const fv=e.target.closest('[data-fav]');if(fv){toggleFavorite(fv.dataset.fav);return}const lc=e.target.closest('[data-live]');if(lc){const c=state.channels.find(x=>x.id===lc.dataset.live);if(c)openPlayer(c);return}const ch=e.target.closest('[data-channel]');if(ch){selectChannel(ch.dataset.channel);return}const ov=e.target.closest('[data-overlay-channel]');if(ov){const c=state.channels.find(x=>x.id===ov.dataset.overlayChannel);if(c){state.currentItem=c;document.getElementById('playerTitle').textContent=c.name;playInto(document.getElementById('mainPlayer'),c.url,true);showChannelOverlay()}return}const gr=e.target.closest('[data-group]');if(gr){state.currentFilter=gr.dataset.group;document.querySelectorAll('[data-group]').forEach(x=>x.classList.toggle('active',x===gr));drawChannelList(document.getElementById('channelSearch')?.value||'');return}const fi=e.target.closest('[data-filter]');if(fi){document.querySelectorAll(`[data-type="${fi.dataset.type}"]`).forEach(x=>x.classList.toggle('active',x===fi));const list=filteredCatalog().filter(x=>x.type===fi.dataset.type&&(fi.dataset.filter==='All'||x.genre===fi.dataset.filter));const id=fi.dataset.type==='movie'?'movies':'series';document.getElementById('grid-'+id).innerHTML=list.map(x=>card(x,true)).join('');return}const ep=e.target.closest('[data-episode]');if(ep){const item=state.catalog.find(x=>x.id===ep.dataset.episode);const episode=item?.episodes?.find(x=>x.num==ep.dataset.episodeNum);if(episode)openPlayer({...episode,id:episode.id,title:`${item.title}: ${episode.title}`,type:'episode'});return}if(e.target.closest('[data-close-details]')){closeDetails();return}if(e.target.classList.contains('switch'))e.target.classList.toggle('on')});
document.addEventListener('input',e=>{if(e.target.id==='globalSearch')drawSearch(e.target.value);if(e.target.id==='channelSearch')drawChannelList(e.target.value)});
document.addEventListener('submit',e=>{if(e.target.id==='openSearchForm'){e.preventDefault();const q=document.getElementById('openSearchInput')?.value.trim()||'';const sort=document.getElementById('openSort')?.value||'downloads desc';loadOpenCinema(state.openCinemaKind,1,q,false,sort)}});document.addEventListener('click',e=>{const od=e.target.closest('[data-open-detail]');if(od){showOpenDetails(od.dataset.openDetail);return}const op=e.target.closest('[data-open-play]');if(op){playOpenItem(op.dataset.openPlay);return}const ok=e.target.closest('[data-open-kind]');if(ok){loadOpenCinema(ok.dataset.openKind,1,'',false,state.openCinemaSort);return}if(e.target.id==='openLoadMore'){loadOpenCinema(state.openCinemaKind,state.openCinemaPage+1,state.openCinemaSearch,true,state.openCinemaSort);return}});
document.getElementById('closePlayer').addEventListener('click',closePlayer);
document.getElementById('playerFav').addEventListener('click',()=>{if(state.currentItem?.id)toggleFavorite(state.currentItem.id);document.getElementById('playerFav').textContent=state.favorites.has(state.currentItem?.id)?'♥':'♡'});
document.getElementById('detailsModal').addEventListener('click',e=>{if(e.target.id==='detailsModal')closeDetails()});
document.addEventListener('change',async e=>{if(e.target.id==='m3uFile'&&e.target.files[0]){const text=await e.target.files[0].text();const channels=parseM3U(text);if(!channels.length)return toast('No channels were found in that M3U file.');const provider={id:'local-m3u-'+Date.now(),name:document.getElementById('m3uProviderName')?.value.trim()||'Local M3U Provider',type:'m3u',territory:(document.getElementById('m3uTerritory')?.value.trim()||'JM').toUpperCase(),priority:40,status:'active',lastSync:new Date().toISOString()};mergeProviderData(provider,channels,[]);renderAdmin();toast(`${channels.length} channels merged`)}if(e.target.id==='xmltvFile'&&e.target.files[0]){const text=await e.target.files[0].text();const parsed=parseXMLTV(text);for(const [k,v] of Object.entries(parsed))state.epg[k]=v;store.set('epg',state.epg);renderAdmin();toast('EPG merged')}if(e.target.id==='catalogFile'&&e.target.files[0]){try{const raw=JSON.parse(await e.target.files[0].text());const provider={id:raw.provider?.id||'json-'+Date.now(),name:raw.provider?.name||'Catalogue JSON',type:raw.provider?.type||'json',territory:(raw.provider?.territory||'JM').toUpperCase(),priority:Number(raw.provider?.priority||50),rightsStart:raw.provider?.rightsStart||null,rightsEnd:raw.provider?.rightsEnd||null,status:'active',lastSync:new Date().toISOString()};mergeProviderData(provider,raw.channels||[],Array.isArray(raw)?raw:(raw.catalog||[]));renderAdmin();toast(`Catalogue merged from ${provider.name}`)}catch(err){toast('Invalid catalogue JSON: '+err.message)}}if(e.target.id==='csvFile'&&e.target.files[0]){try{const provider={id:'csv-'+Date.now(),name:document.getElementById('csvProviderName')?.value.trim()||'Distributor CSV',type:'csv',territory:(document.getElementById('csvTerritory')?.value.trim()||'JM').toUpperCase(),priority:50,status:'active',lastSync:new Date().toISOString()};const items=csvToCatalog(await e.target.files[0].text(),provider);if(!items.length)throw new Error('No valid title rows found');mergeProviderData(provider,[],items);renderAdmin();toast(`${items.length} distributor records merged`)}catch(err){toast('CSV import failed: '+err.message)}}});
document.addEventListener('click',async e=>{if(e.target.id==='restoreDemo'){mergeProviderData(DEMO_PROVIDER,DEMO_CHANNELS,DEMO_CATALOG);renderAdmin();toast('Open demo source added')}if(e.target.id==='connectorSync')connectProvider();if(e.target.id==='saveTerritory'){state.territory=document.getElementById('territorySelect')?.value||'JM';persist();renderAll();showView('admin');toast(`Territory set to ${state.territory}`)}const rm=e.target.closest('[data-remove-source]');if(rm){const id=rm.dataset.removeSource;try{if(location.protocol.startsWith('http'))await fetch(`/api/providers/${id}`,{method:'DELETE'})}catch{}removeProviderLocal(id);showView('admin');toast('Source removed')}if(e.target.id==='resetApp'){['channels','catalog','epg','favorites','progress','history','profile','providers','territory'].forEach(k=>localStorage.removeItem('velora_'+k));location.reload()}if(e.target.id==='openFullLive'&&state.currentChannel)openPlayer(state.currentChannel)});
window.addEventListener('keydown',e=>{if(document.getElementById('playerOverlay').classList.contains('on')){if(e.key==='Escape'||e.key==='Backspace'){e.preventDefault();closePlayer()}if((e.key==='ArrowUp'||e.key==='ArrowDown')&&state.currentItem?.name){e.preventDefault();const live=filteredChannels();const i=live.findIndex(x=>x.id===state.currentItem.id);const n=e.key==='ArrowUp'?Math.max(0,i-1):Math.min(live.length-1,i+1);const c=live[n];if(c){state.currentItem=c;document.getElementById('playerTitle').textContent=c.name;playInto(document.getElementById('mainPlayer'),c.url,true);showChannelOverlay()}}}});
if('serviceWorker' in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});